css:
.am-empty { padding: 60px 0; display: flex; flex-direction: column; align-items: flex-start; gap: 18px; }
.am-empty[hidden], .am[hidden] { display: none; }
.am-empty p { margin: 0; font-size: 17px; color: #c4d4e2; line-height: normal; }
.am-clear { font-family: var(--font-heading); font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase; font-size: 13px; color: #00fbff; background: transparent; border: 1px solid #00cdfd; padding: 12px 22px; border-radius: 4px; cursor: pointer; }
.am { display: flex; justify-content: center; padding-top: 56px; }
.am-btn { font-family: var(--font-heading); font-weight: 600; letter-spacing: 0.12em; text-transform: uppercase; font-size: 14px; color: #020617; background: linear-gradient(135deg, #00fbff, #00cdfd); border: 0; padding: 14px 32px; border-radius: 4px; cursor: pointer; }
